 "Captures and imports": "캡처 및 가져오기",
 "Observed profiles, equipment, counters and order history. Coverage depends on what the game sends during collection.": "관찰된 프로필, 장비, 카운터, 주문 기록. 수집 중 게임이 보내는 내용에 따라 범위가 달라집니다.",
 "Editorial content": "편집 콘텐츠",
 "Readable names, explanations, artwork selections, team presets and some schedules, maintained separately from extracted game facts.": "읽기 쉬운 이름, 설명, 일러스트 선정, 팀 프리셋, 일부 일정. 추출된 게임 정보와 별도로 관리합니다.",
 "How each section uses the data": "각 섹션이 데이터를 사용하는 방식",
 "Shared references feed several pages. Each feature selects the relevant records and adds its own presentation or calculations.": "공유 참조 데이터가 여러 페이지를 뒷받침합니다. 각 기능은 관련 레코드를 골라 자체 표시나 계산을 더합니다.",
