 "Bygone and Sequential": "Bygone과 Sequential",
 "Team raids": "팀 레이드",
 "Items and Handbook": "아이템과 핸드북",
 "Item records, localized text and icons form the item catalog. Handbook combines progression and equipment references into comparisons and tables.": "아이템 레코드, 현지화 텍스트, 아이콘이 아이템 카탈로그를 이룹니다. 핸드북은 성장과 장비 참고 자료를 비교표로 묶었습니다.",
