 "Ranking and player profiles": "랭킹과 플레이어 프로필",
 "Wish Tracker and simulator": "뽑기 기록과 시뮬레이터",
 "Team and raid compositions": "팀 및 레이드 편성",
 "From an installed game to an update": "설치된 게임에서 업데이트까지",
 "The portable exporter runs the processing pipeline near the installed client. The website consumes its finished datasets and media.": "휴대용 내보내기 도구는 설치된 클라이언트 근처에서 처리 파이프라인을 실행합니다. 웹사이트는 완성된 데이터셋과 미디어를 사용합니다.",
 "Identify the client": "클라이언트 식별",
 "Read installation and launcher metadata to record the exported version and branch.": "설치 및 런처 메타데이터를 읽어 내보낸 버전과 브랜치를 기록합니다.",
 "Extract selected resources": "선택한 리소스 추출",
 "UnrealExporter reads configured paths from the game archives: tables, localization and the textures needed by the site.": "UnrealExporter가 게임 아카이브에서 설정된 경로(표, 현지화, 사이트에 필요한 텍스처)를 읽습니다.",
 "Process and connect": "처리 및 연결",
 "Processors resolve identifiers and join tables to translations and media. Separate curated inputs add labels, notes and preserved resources.": "프로세서가 식별자를 해석하고 표를 번역 및 미디어와 연결합니다. 별도로 선별한 입력이 라벨, 메모, 보존 리소스를 추가합니다.",
 "Generate the site data": "사이트 데이터 생성",
 "Validate and package": "검증 및 패키징",
 "Apply and publish": "적용 및 게시",
 "The update is applied to the site’s generated public files and checked before deployment. Exporting a client does not itself publish the website.": "업데이트는 사이트의 생성된 공개 파일에 적용되고 배포 전에 확인됩니다. 클라이언트를 내보낸다고 해서 웹사이트가 저절로 게시되지는 않습니다.",
 "ToF Hub Live Capture": "ToF Hub 라이브 캡처",
 "Start before logging in": "로그인 전에 시작",
 "Choose a task and follow the readiness checks. The app uses the WinDivert driver to observe network traffic and asks for Windows administrator rights.": "작업을 선택하고 준비 점검을 따르세요. 앱은 WinDivert 드라이버로 네트워크 트래픽을 관찰하며 Windows 관리자 권한을 요청합니다.",
 "Follow the in-game prompts": "게임 내 안내 따르기",
 "Save and import": "저장 및 가져오기",
 "Import files": "파일 가져오기",
 "Checks and limits": "검증 및 한계",
 "Keep the source attached": "출처 유지",
 "Record the source branch, export or capture time and known provenance. A test client can contain unreleased or unused records.": "원본 브랜치, 내보내기 또는 캡처 시각, 알려진 출처를 기록하세요. 테스트 클라이언트에는 미출시 또는 미사용 레코드가 있을 수 있습니다.",
 "Check relationships and calculations": "관계와 계산 확인",
 "Show uncertainty": "불확실성 표시",
 "Separate edits from observations": "편집과 관찰 분리",
 "A few file terms": "파일 용어 몇 가지",
 "Unreal Engine archives and individual assets. Tables, configuration and textures are exported into readable formats.": "Unreal Engine 아카이브와 개별 에셋. 표, 설정, 텍스처는 읽기 쉬운 형식으로 내보냅니다.",
 "Localization supplies game text. JSON is the exported or generated representation used by the processors and website.": "현지화는 게임 텍스트를 제공합니다. JSON은 프로세서와 웹사이트가 사용하는 내보내기/생성 형식입니다.",
 "Extracted textures are converted for display. WebP serves the site; PNG is retained for supported original-image downloads.": "추출한 텍스처는 표시용으로 변환됩니다. 사이트는 WebP를 사용하고, 지원되는 원본 이미지 다운로드용으로 PNG를 보존합니다.",
 "Questions, corrections and updates": "질문, 정정, 업데이트",
