 "Info": "도감",
 "Tools": "도구",
 "Build cards, gear optimizer, wish history, squad compositions and rankings. Game-capture imports, stored player records and a processing queue.": "빌드 카드, 장비 최적화, 뽑기 기록, 분대 편성, 랭킹. 게임 캡처 가져오기, 저장된 플레이어 기록, 처리 대기열.",
