 "Hub & Site": "허브 및 사이트",
 "Site": "사이트",
 "Updated the dataset to 6.4.10, added the main hub and version history, and corrected MMO data processing.": "데이터셋을 6.4.10으로 업데이트하고 메인 허브와 버전 기록을 추가했으며 MMO 데이터 처리를 수정했습니다.",
 "Added the main hub with Info, Tools and Datamine shortcuts. Version branches are grouped separately; history and patcher instructions open in dialogs.": "도감, 도구, 데이터 분석 바로가기가 있는 메인 허브를 추가했습니다. 버전 브랜치는 따로 묶였고, 기록과 패처 안내는 대화상자에서 열립니다.",
 "Feature": "기능",
 "Data": "데이터",
 "Corrected MMO round and enemy references and regional season dates. Missing season floors are no longer copied from another season.": "MMO 라운드와 적 참조, 지역별 시즌 날짜를 수정했습니다. 누락된 시즌 층을 더 이상 다른 시즌에서 복사하지 않습니다.",
 "Added a separate gold quality for MMO food in the pipeline, cards and rarity filter.": "파이프라인, 카드, 등급 필터에 MMO 요리용 별도 금색 품질을 추가했습니다.",
 "Complete visual overhaul of Origin of War: progressive image loading, WebP asset optimization, responsive season cards, and deep-link affix breakdown.": "Origin of War 전면 개편: 점진적 이미지 로딩, WebP 에셋 최적화, 반응형 시즌 카드, 딥링크 접두사 분석.",
 "Updated Datamine data for version 6.3.0.": "데이터 분석 데이터를 버전 6.3.0으로 업데이트했습니다.",
 "Updated Season 23 data, enemy waves, and boss values.": "시즌 23 데이터, 적 웨이브, 보스 값을 업데이트했습니다.",
 "Updated boss stages and calculated scaling values.": "보스 스테이지와 계산된 성장 값을 업데이트했습니다.",
 "Added new boss mechanics and refreshed boss cards.": "새 보스 기믹을 추가하고 보스 카드를 갱신했습니다.",
 "Updated Gacha and MMO item databases.": "가챠 및 MMO 아이템 데이터베이스를 업데이트했습니다.",
 "Updated Multype data from the latest full game scan.": "최신 전체 게임 스캔으로 Multype 데이터를 업데이트했습니다.",
 "Small data and site update.": "소규모 데이터 및 사이트 업데이트.",
 "Added missing boss descriptions and updated the boss list.": "누락된 보스 설명을 추가하고 보스 목록을 업데이트했습니다.",
 "Updated season data and buff descriptions.": "시즌 데이터와 버프 설명을 업데이트했습니다.",
 "Fixed several item names and mappings.": "여러 아이템 이름과 매핑을 수정했습니다.",
 "Small layout and localization fixes.": "레이아웃 및 현지화 소규모 수정.",
 "Changelog | ToF Hub": "변경 내역 | ToF Hub",
 "Filter by section": "섹션별 필터",
 "CONTRIBUTE": "기여하기",
 "Help improve ToF Hub": "ToF Hub 개선에 도움을 주세요",
 "Provide a fresh game export, help with a Multype research scan or report a data error. Each option is independent: pick the one that fits your time.": "최신 게임 내보내기를 제공하거나, Multype 연구 스캔을 돕거나, 데이터 오류를 신고할 수 있습니다. 각 방법은 독립적이니 시간에 맞는 것을 고르세요.",
