 "Run it and choose the game": "실행하고 게임 선택",
 "Send the archive to the developer": "아카이브를 개발자에게 보내기",
 "What to include in a report": "신고에 포함할 내용",
 "Include as much of the following as possible to help reproduce and fix the issue quickly:": "문제를 빠르게 재현하고 고칠 수 있도록 다음 내용을 가능한 한 많이 포함해 주세요:",
 "Exact page URL and feature section (e.g. /datamine/oow/?s=23&floor=25)": "정확한 페이지 URL과 기능 섹션 (예: /datamine/oow/?s=23&floor=25)",
 "Game region and client version (e.g. Korea Dev 2 · 6.4.10)": "게임 지역과 클라이언트 버전 (예: Korea Dev 2 · 6.4.10)",
 "Screenshot or excerpt from the official game client showing the expected value": "기대하는 값을 보여 주는 공식 게임 클라이언트의 스크린샷 또는 발췌",
 "Item ID, monster key, or buff attribute name if known": "아는 경우 아이템 ID, 몬스터 키, 버프 속성 이름",
 "Clear explanation of why the current value is incorrect": "현재 값이 잘못된 이유에 대한 명확한 설명",
 "Send reports and questions through the public repository:": "신고와 질문은 공개 저장소로 보내 주세요:",
 "Open GitHub Issues": "GitHub Issues 열기",
 "Contribute | ToF Hub": "기여하기 | ToF Hub",
 "Contribution workflows": "기여 방법",
 "OFFICIAL SHOP & PAYMENT LINK BUILDER": "공식 상점 및 결제 링크 생성기",
 "Donation & Pack Catalog": "후원 및 패키지 카탈로그",
 "Explore paid packs, battle passes, and supply bundles. Generate official direct purchase links using your game client account parameters.": "유료 패키지, 배틀 패스, 보급 번들을 살펴보세요. 게임 클라이언트 계정 정보로 공식 직접 구매 링크를 생성합니다.",
 "Client-Side Privacy:": "클라이언트 측 개인정보 보호:",
 "Account parameters are processed 100% in your browser and never sent to any server.": "계정 정보는 브라우저에서 100% 처리되며 어떤 서버로도 전송되지 않습니다.",
 "Purchase Link Builder": "구매 링크 생성기",
 "Paste any line from HottaBrowser.log to auto-fill your account IDs, pick a pack, and open your order link.": "HottaBrowser.log의 아무 줄이나 붙여넣으면 계정 ID가 자동 입력됩니다. 패키지를 고르고 주문 링크를 여세요.",
 "Paste HottaBrowser.log URL or line:": "HottaBrowser.log URL 또는 줄 붙여넣기:",
 "User ID:": "사용자 ID:",
 "Server ID:": "서버 ID:",
 "Role ID:": "역할 ID:",
 "Selected Pack:": "선택한 패키지:",
 "Monthly Pass (30 Days)": "월간 패스 (30일)",
 "Official Order Link (create.do):": "공식 주문 링크 (create.do):",
 "Please fill in User ID, Server ID, and Role ID first": "먼저 사용자 ID, 서버 ID, 역할 ID를 입력하세요",
 "1. Generate Order Link": "1. 주문 링크 생성",
 "Copy Link": "링크 복사",
 "Step 2: Proceed to Razer Checkout": "2단계: Razer 결제로 진행",
 "After opening the order link, paste the returned JSON or payUrl below to proceed:": "주문 링크를 연 뒤 반환된 JSON 또는 payUrl을 아래에 붙여넣어 진행하세요:",
 "2. Proceed to Razer Checkout": "2. Razer 결제로 진행",
