 "ToF Resources & Projects": "TOF 자료 및 프로젝트",
 "Paste item link": "아이템 링크 붙여넣기",
 "Link from Arts": "일러스트 링크",
 "Paste an avatar or frame link": "아바타 또는 프레임 링크 붙여넣기",
 "Paste a link from Arts: /info/arts/#…": "일러스트 링크 붙여넣기: /info/arts/#…",
 "No matching item found.": "일치하는 아이템을 찾을 수 없습니다.",
 "Artwork not found. Paste a link from /info/arts/.": "일러스트를 찾을 수 없습니다. /info/arts/ 링크를 붙여넣으세요.",
 "Not in this file": "이 파일에 없음",
 "Without a count": "개수 없음",
 "Augmentation spent": "사용한 증폭",
 "Total Aug": "총 증폭",
 "Model estimate": "모델 추정치",
 "How to read these formulas": "이 공식을 읽는 방법",
 "Capture, bonuses and inheritance": "캡처, 보너스, 상속",
 "Combat-stat formulas": "전투 능력치 공식",
 "Game curves": "게임 곡선",
 "Curve values in this catalog": "이 카탈로그의 곡선 값",
 "Crit denominator · enemy Lv. 100": "치명타 분모 · 적 Lv. 100",
 "This is one curve point; changing enemy level uses its own point, not this constant.": "곡선의 한 점입니다. 적 레벨을 바꾸면 이 상수가 아니라 해당 레벨의 점을 사용합니다.",
 "Defence K · character Lv. 100": "방어 K · 캐릭터 Lv. 100",
 "Resistance reduction uses character level independently of the selected Crit enemy level.": "저항 감소는 선택한 치명타 적 레벨과 무관하게 캐릭터 레벨을 사용합니다.",
 "CS coefficients in this catalog": "이 카탈로그의 전투력 계수",
 "B: full base before percentages": "B: 백분율 적용 전 전체 기준값",
 "Fixed coefficient per fraction 1.0; 1 percentage point contributes weight / 100.": "비율 1.0당 고정 계수. 1퍼센트포인트는 가중치 / 100을 더합니다.",
 "Per one flat stat point.": "고정 능력치 1포인트당.",
 "Titan-property CS coefficients": "타이탄 속성 전투력 계수",
 "The coefficient is unknown; this component cannot be calculated.": "계수를 알 수 없어 이 항목은 계산할 수 없습니다.",
 "Generated from the game attribute weight. Use the curve value at this item’s level before display formatting.": "게임 속성 가중치에서 생성되었습니다. 표시 서식 이전의 이 아이템 레벨 곡선 값을 사용하세요.",
 "Rolls and Titan forecasts": "롤과 타이탄 예측",
 "Forecast limits in this catalog": "이 카탈로그의 예측 한도",
 "Random / added stat limits": "무작위 / 추가 능력치 한도",
 "Slot-specific allowed stat types still apply; the limit does not permit any arbitrary combination.": "슬롯별로 허용되는 능력치 종류는 그대로 적용됩니다. 이 한도는 임의의 조합을 허용하지 않습니다.",
 "Upgrade-roll limit": "강화 롤 한도",
 "The full forecast uses this limit, while current rating counts the values the item actually has.": "전체 예측은 이 한도를 사용하고, 현재 평가는 아이템이 실제로 가진 값을 셉니다.",
 "Observed added-stat share": "관찰된 추가 능력치 비율",
 "Calibration from captured items. This is the model’s forecast share, not a verified chance or guaranteed upper bound.": "캡처한 아이템에서 보정한 값입니다. 모델의 예측 비율이며 검증된 확률이나 보장된 상한이 아닙니다.",
 "Pull-up rank factors": "풀업 등급 계수",
 "? marks an unconfirmed rank that the model does not project.": "?는 모델이 예측하지 않는 미확인 등급을 뜻합니다.",
 "What the capture contains": "캡처에 포함된 내용",
 "The pair inherits whole gear percentages": "짝은 장비 백분율을 통째로 상속합니다",
