 "Titan maximum and pull-up": "타이탄 최대값과 풀업",
 "Titan-added stat forecast": "타이탄 추가 능력치 예측",
 "Date and time unavailable": "날짜와 시간을 사용할 수 없음",
 "Fixed base stats, enhancement and unlocked base bonuses.": "고정 기본 능력치, 강화, 해금된 기본 보너스.",
 "Gear · base + enhancement": "장비 · 기본 + 강화",
 "Initial random values, upgrade rolls and Titan additions.": "초기 무작위 값, 강화 롤, 타이탄 추가분.",
