 "Crit DMG bonus": "치명타 DMG 보너스",
 "Weapon and matrix damage in gear comparisons": "장비 비교의 무기 및 칩셋 피해",
 "Why weapon and matrix damage multipliers are separate": "무기와 칩셋 피해 배율이 따로 계산되는 이유",
 "Q: largest weighted maximum roll after the Titan multiplier, across the generated stat catalog.": "Q: 생성된 능력치 카탈로그 전체에서, 타이탄 배율 적용 후 가중 최대 롤의 최댓값.",
 "Q: largest weighted maximum roll after the Titan multiplier among the stats this role rates.": "Q: 이 역할이 평가하는 능력치 중, 타이탄 배율 적용 후 가중 최대 롤의 최댓값.",
 "Titan-added stats: why equal rolls can give different HP": "타이탄 추가 능력치: 같은 롤이어도 HP가 다르게 나오는 이유",
 "Equivalent rolls = (primary after Titan − primary initial value) / primary maximum roll": "동등 롤 = (타이탄 적용 후 주 능력치 − 주 능력치 초기값) / 주 능력치 최대 롤",
 "Added stat = its initial value + observed share × equivalent rolls × its maximum roll": "추가 능력치 = 초기값 + 관찰된 비율 × 동등 롤 × 해당 능력치의 최대 롤",
 "enemy-level denominator": "적 레벨 분모",
 "Both Crit weights are zero when c ≥ 1.": "c ≥ 1이면 두 치명타 가중치는 모두 0입니다.",
 "Equipped gear": "장착 장비",
 "Build maximum": "빌드 최대치",
 "Build roll quality": "빌드 롤 품질",
 "Equip at least one item and provide valid rating inputs for every equipped slot. Empty slots add no points; their ceilings remain part of the build maximum.": "아이템을 하나 이상 장착하고, 장착된 모든 슬롯에 유효한 평가 입력을 넣으세요. 빈 슬롯은 점수를 더하지 않지만 상한은 빌드 최대치에 그대로 포함됩니다.",
 "Total of the equipped items’ GRV against the total of their slot ceilings, using one reference profile for everyone.": "장착 아이템들의 GRV 합계를 슬롯 상한 합계와 비교합니다. 모든 사용자에게 같은 기준 프로필을 사용합니다.",
 "Total of the equipped items’ PRV against the total of their slot ceilings, using your current panel stats.": "장착 아이템들의 PRV 합계를 슬롯 상한 합계와 비교합니다. 현재 패널 능력치를 사용합니다.",
 "Sum of the slot scores. Open the RV of an item for its own breakdown.": "슬롯 점수의 합계입니다. 아이템의 RV를 열면 개별 내역을 볼 수 있습니다.",
 "Share of the build maximum. It is not a damage bonus or a ranking among players.": "빌드 최대치 대비 비율입니다. 피해 보너스나 플레이어 간 순위가 아닙니다.",
 "Each item is rated after removing only that item, so the total is not the effect of removing or adding the whole set at once.": "각 아이템은 해당 아이템만 제외한 상태로 평가되므로, 합계는 세트 전체를 한 번에 빼거나 더했을 때의 효과가 아닙니다.",
 "Total Global Roll Value": "전체 글로벌 롤 값",
 "Total Personal Roll Value": "전체 개인 롤 값",
 "Total ": "합계 ",
 "Current stats": "현재 능력치",
 "Slot ceiling": "슬롯 상한",
 "Slot roll quality": "슬롯 롤 품질",
 "of slot ceiling": "슬롯 상한 대비",
 "Enter base ATK, ATK%, DMG%, Crit and a supported enemy level. Totals must include this equipped item and remain valid after removal.": "기본 공격력, 공격력%, DMG%, 치명타 및 지원되는 적 레벨을 입력하세요. 합계에는 이 장착 아이템이 포함되어야 하며 제거 후에도 유효해야 합니다.",
 "Enter all four pre-Titan stats.": "타이탄 이전의 능력치 네 개를 모두 입력하세요.",
 "The source does not confirm this pull-up case.": "출처에서 이 픽업 상승 사례를 확인할 수 없습니다.",
 "Check SSR stat ranges and stars.": "SSR 능력치 범위와 별을 확인하세요.",
 "Tied strongest stats: conservative estimate.": "동점인 가장 강한 능력치: 보수적 추정치.",
 "One reference profile for everyone. Compare tank gear as it is now by the effective HP it adds against the selected element, independently of account stats.": "모든 사용자에게 같은 기준 프로필을 사용합니다. 계정 능력치와 무관하게, 선택한 속성 기준으로 현재 상태의 탱커 장비가 추가하는 실효 HP로 비교합니다.",
 "One reference profile for everyone. Compare healer gear as it is now by the ATK it adds, independently of account stats.": "모든 사용자에게 같은 기준 프로필을 사용합니다. 계정 능력치와 무관하게, 현재 상태의 힐러 장비가 추가하는 공격력으로 비교합니다.",
 "One reference profile for everyone. Compare offensive gear as it is now in the same element and weapon context, independently of account stats.": "모든 사용자에게 같은 기준 프로필을 사용합니다. 계정 능력치와 무관하게, 같은 속성과 무기 조건에서 현재 상태의 공격 장비를 비교합니다.",
 "The current equipped item is subtracted first. Its current stats are then rated using the remaining build, rather than added on top of its own current stats.": "현재 장착된 아이템을 먼저 뺍니다. 그 뒤 나머지 빌드를 기준으로 현재 능력치를 평가하며, 아이템의 현재 능력치를 그 위에 더하지 않습니다.",
 "Share of this slot’s theoretical ceiling, not extra damage or a ranking among players.": "이 슬롯의 이론적 상한 대비 비율입니다. 추가 피해나 플레이어 간 순위가 아닙니다.",
