 "Personal reference unavailable. GRV is available through the switch below the card.": "개인 기준을 사용할 수 없습니다. 카드 아래 전환 버튼으로 GRV를 볼 수 있습니다.",
 "These baseline values are site assumptions, not official game constants. Your buffs, enemy level and current Crit do not change GRV weights.": "이 기준값은 사이트의 가정이며 공식 게임 상수가 아닙니다. 버프, 적 레벨, 현재 치명타는 GRV 가중치를 바꾸지 않습니다.",
