 "Auto · weapon resonance": "자동 · 무기 공명",
 "MMO build editor": "MMO 빌드 편집기",
 "Enter the values of the in-game attribute screens; leave a field empty when it is unknown.": "게임 내 능력치 화면의 값을 입력하세요. 값을 모르면 칸을 비워 두세요.",
