 "MMO build card help": "MMO 빌드 카드 도움말",
 "About the MMO card": "MMO 카드 정보",
 "My MMO builds": "내 MMO 빌드",
 "Public MMO builds": "공개 MMO 빌드",
 "A showcase card of a Warp (MMO) character, filled from your own .tofbuild capture or by hand.": "Warp(MMO) 캐릭터의 쇼케이스 카드이며, 내 .tofbuild 캡처 또는 직접 입력으로 채워집니다.",
 "What the import fills": "가져오기로 채워지는 항목",
 "Name, UID, level, CS, crew, title, avatar and frame from the login.": "로그인 시 받은 이름, UID, 레벨, 전투력, 승무원, 칭호, 아바타 및 프레임.",
 "Attributes and equipment": "속성 및 장비",
 "The attribute panel, 12 gear slots with their random stats and the expansion card of each slot.": "속성 패널, 무작위 능력치가 있는 장비 슬롯 12개, 그리고 각 슬롯의 확장 카드.",
 "Three weapons with +N and the weapon mode (Regular / Fixed-damage).": "+N 강화 무기 세 개와 무기 모드(일반 / 고정 피해).",
 "Node levels; hover a chain for its stat sums.": "노드 레벨. 체인에 마우스를 올리면 능력치 합계를 볼 수 있습니다.",
 "Smart Servant and food": "스마트 서번트와 요리",
 "The pet with its inherited ATK and the active dishes. An empty slot shows \"Nothing\".": "상속 공격력을 가진 펫과 활성 요리. 빈 슬롯은 “없음”으로 표시됩니다.",
 "Parts the game did not send at this login stay empty and are listed after the import. Open those windows in the game and capture again.": "이번 로그인에서 게임이 보내지 않은 부분은 빈 상태로 남으며 가져온 뒤 목록으로 표시됩니다. 게임에서 해당 창을 열고 다시 캡처하세요.",
 "Saving and public builds": "저장과 공개 빌드",
 "One build per role": "역할별 빌드 하나",
 "Choose DPS, Tank, Healer or Balance at the top right of the card and press \"Save build\". Each role keeps its own public card.": "카드 오른쪽 위에서 DPS, 탱커, 힐러 또는 밸런스를 선택하고 “빌드 저장”을 누르세요. 역할마다 각자의 공개 카드가 유지됩니다.",
 "Only the unedited import": "수정하지 않은 가져오기만 가능",
 "The site stores the signed capture, so value edits block saving. Role and background are free choices.": "사이트는 서명된 캡처를 저장하므로 값을 수정하면 저장이 차단됩니다. 역할과 배경은 자유롭게 바꿀 수 있습니다.",
 "Live Warp servers": "운영 중인 Warp 서버",
 "Test-server, DEV-client and unresolved captures are shown but never saved.": "테스트 서버, DEV 클라이언트 및 해결되지 않은 캡처는 표시되지만 저장되지 않습니다.",
 "MMO has no ranking, Wish Tracker or gear optimizer on the site.": "MMO에는 사이트의 순위, Wish Tracker 또는 장비 최적화 도구가 없습니다.",
