 "Order by maximum CS; places remain the original GRV places.": "최대 전투력 순으로 정렬합니다. 순위는 원래 GRV 순위를 유지합니다.",
 "With inheritance": "상속 포함",
 "Rated stats": "평가된 능력치",
 "Values before Titan and roll counts": "타이탄 이전 값과 롤 횟수",
 "Current values and Titan progress": "현재 값과 타이탄 진행",
 "Verified Titan · own .tofbuild": "검증된 타이탄 · 본인 .tofbuild",
 "All pieces: verified Titan · own .tofbuild": "모든 부품: 검증된 타이탄 · 본인 .tofbuild",
 "Every piece behind this score is Titan from the player’s own .tofbuild, with known original stats.": "이 점수의 모든 부품은 플레이어 본인의 .tofbuild에서 가져온 타이탄 아이템이며 원래 능력치를 알고 있습니다.",
 "Titan item from the player’s own .tofbuild, with known original stats. Inspected and non-Titan gear is not verified.": "플레이어 본인의 .tofbuild에서 가져온 타이탄 아이템이며 원래 능력치를 알고 있습니다. 검사되지 않았거나 타이탄이 아닌 장비는 검증되지 않았습니다.",
 "Counted stats converted into rating points; 100 = the most valuable single roll at full Titan across all stats.": "계산에 포함된 능력치를 평가 점수로 환산한 값입니다. 100 = 모든 능력치 중 완전한 타이탄 상태에서 가장 가치 있는 단일 롤.",
 "universal ATK, the element’s ATK, ATK % and DMG %, Crit and Crit Rate %; other stats give 0.": "범용 공격력, 속성 공격력, 공격력% 및 DMG%, 치명타 및 치명타율%; 다른 능력치는 0점입니다.",
 "the better flat ATK, ATK % and DMG % of either element of the pair; Crit counts, other stats give 0.": "짝의 두 속성 중 더 높은 고정 공격력, 공격력% 및 DMG%; 치명타는 계산되며, 다른 능력치는 0점입니다.",
 "The perfect item of the slot: the best legal set of counted stats, every roll on the most valuable one, at full Titan (100 %).": "슬롯의 완벽한 아이템: 계산에 포함된 능력치 중 합법적인 최선의 조합이며, 가장 가치 있는 능력치에 모든 롤을 넣고 완전한 타이탄(100 %) 상태로 가정합니다.",
 "Current values of each item. Titan growth is random, so other players’ values before Titan cannot be recovered.": "각 아이템의 현재 값입니다. 타이탄 성장은 무작위이므로 타이탄 이전의 다른 플레이어 값은 복구할 수 없습니다.",
 "Reference player": "기준 플레이어",
 "These baseline values are site assumptions, not official game constants; crit uses the game’s crit formula at this enemy level.": "이 기준값은 사이트의 가정이며 공식 게임 상수가 아닙니다. 치명타는 이 적 레벨에서 게임의 치명타 공식을 사용합니다.",
 "One reference profile for everyone: each stat is rated by the ATK it adds to the same reference player (crit and DMG % are not rated).": "모든 사용자에게 같은 기준 플레이어를 사용합니다. 각 능력치는 같은 기준 플레이어에게 더하는 공격력으로 평가됩니다(치명타와 DMG %는 평가하지 않음).",
 "One reference profile for everyone: each stat is rated by the effective HP it adds against the selected element to the same reference tank.": "모든 사용자에게 같은 기준 플레이어를 사용합니다. 각 능력치는 같은 기준 탱커에게 선택한 속성에 대해 더하는 실효 HP로 평가됩니다.",
 "Counted stats converted into rating points; 100 = the most valuable single roll at full Titan among the stats this role rates.": "계산에 포함된 능력치를 평가 점수로 환산한 값입니다. 100 = 이 역할이 평가하는 능력치 중 완전한 타이탄 상태에서 가장 가치 있는 단일 롤.",
 "universal ATK, the element’s ATK and ATK %; crit, DMG % and other stats give 0.": "범용 공격력, 속성 공격력 및 공격력%; 치명타, DMG % 및 다른 능력치는 0점입니다.",
 "HP, HP %, general RES (counts like the element’s own), the element’s RES and RES %; other stats give 0.": "HP, HP %, 범용 저항(속성 저항과 같이 계산), 속성 저항 및 RES %; 다른 능력치는 0점입니다.",
 "These baseline values are site assumptions, not official game constants; damage reduction uses the game’s defence formula at this level.": "이 기준값은 사이트의 가정이며 공식 게임 상수가 아닙니다. 피해 감소는 이 레벨에서 게임의 방어 공식을 사용합니다.",
 "All elements · best element of each server": "모든 속성 · 서버별 최고 속성",
 "Added by Titan: this stat did not exist before Titan": "타이탄으로 추가됨: 이 능력치는 타이탄 이전에는 없었습니다",
 "GRV of the perfect item of the slot (100 %)": "슬롯의 완벽한 아이템의 GRV(100 %)",
