 "Titan growth so far: share of the way from the value before Titan to the full-Titan maximum (Titan-added stats: current value / maximum)": "지금까지의 타이탄 성장: 타이탄 이전 값에서 완전한 타이탄 최대치까지의 진행률(타이탄으로 추가된 능력치: 현재 값 / 최대치)",
 "Titan maximum": "타이탄 최대치",
