 "Damage taken relative to health: includes HP and resistance. Lower is better; the ratio is the inverse of effective HP.": "체력 대비 받는 피해: HP와 저항을 포함합니다. 낮을수록 좋으며, 이 비율은 실효 HP의 역수입니다.",
