 "If you need a public account with all Global regions and access to the ranking, you can use these credentials:": "모든 Global 지역과 랭킹 접근이 가능한 공개 계정이 필요하면 아래 자격 증명을 사용할 수 있습니다:",
 "Double-click to select and copy the whole value. Enter or Space also copies.": "두 번 클릭하면 전체 값을 선택하고 복사합니다. Enter 또는 Space도 복사합니다.",
