 "Capture your own build": "내 빌드 캡처",
 "Use the capture app on your PC, save your character as .tofbuild and upload the file to update their data.": "PC의 캡처 앱을 사용해 캐릭터를 .tofbuild로 저장하고 파일을 업로드하면 데이터가 갱신됩니다.",
 "How to collect .tofbuild": ".tofbuild 수집 방법",
 "Ask another player": "다른 플레이어에게 요청",
 "Someone else can use the app, open your profile in the game and upload .tofplayers. They do not need access to your account.": "다른 사람이 앱을 사용할 수 있으면 게임에서 프로필을 열고 .tofplayers를 업로드하세요. 그 사람이 내 계정에 접근할 필요는 없습니다.",
 "How to collect .tofplayers": ".tofplayers 수집 방법",
 "Outdated data or a missing character? There are two ways to update the ranking.": "데이터가 오래되었거나 캐릭터가 없나요? 랭킹을 갱신하는 방법은 두 가지입니다.",
 "Ways to update": "갱신 방법",
