 ".locres / JSON": ".locres / JSON",
 "PNG / WebP": "PNG / WebP",
 "ToF | Contribute": "ToF | 기여하기",
 "Help keep ToF Hub current by providing a fresh Tower of Fantasy game export for regular Datamine updates, Multype research scans, or manual data corrections.": "정기 Datamine 업데이트, Multype 연구 스캔 또는 수동 데이터 수정을 위해 최신 Tower of Fantasy 게임 내보내기를 제공하여 ToF Hub를 최신 상태로 유지하세요.",
 "ToFExporter.exe --game-path \"D:\\Tower of Fantasy\"": "ToFExporter.exe --game-path \"D:\\Tower of Fantasy\"",
 "Export ~1–2 h · Scan ~5 min": "내보내기 ~1–2시간 · 스캔 ~5분",
 "Export and unpack the full game": "전체 게임 내보내기 및 압축 풀기",
