 "Run the scanner": "스캐너 실행",
 "Execute the scanner CLI against your JSON export folder to map AttributeName, Modifiers, and ModuleExtraType relationships:": "JSON 내보내기 폴더를 대상으로 스캐너 CLI를 실행하여 AttributeName, Modifiers, ModuleExtraType 관계를 매핑하세요:",
 "python main_scanning_files.py --input path_to_json --mode 1": "python main_scanning_files.py --input path_to_json --mode 1",
