 "Standard and purple banners have no 50/50 mechanic — all SSR drops are from the standard pool.": "일반 및 보라 배너에는 50/50 규칙이 없습니다. 모든 SSR 드롭은 일반 풀에서 나옵니다.",
 "50/50 Win Rate": "50/50 승률",
 "SSR Drop Rate": "SSR 드롭률",
 "Both Metrics": "두 지표 모두",
 "Very Lucky": "매우 운이 좋음",
 "Very Unlucky": "매우 운이 나쁨",
 "You won the featured pull {{wins}} of {{total}} times ({{rate}}%); the classic baseline is 50.0%.": "픽업 뽑기에서 {{total}}번 중 {{wins}}번 승리했습니다 ({{rate}}%). 기본 기준은 50.0%입니다.",
 "Insufficient data for luck assessment": "운 평가를 위한 데이터가 부족합니다",
 "Special Orders Mechanics (Tower of Fantasy)": "특별 주문 메커니즘 (Tower of Fantasy)",
 "Rates, hard guarantees, and event order economy. Base odds and the average SSR rate are shown separately.": "확률, 하드 보장 및 이벤트 주문 경제. 기본 확률과 평균 SSR 확률은 따로 표시됩니다.",
 "Rates & guarantees": "확률 및 보장",
 "The base rate applies to an individual pull before a guarantee triggers.": "기본 확률은 보장이 발동되기 전 개별 뽑기에 적용됩니다.",
 "Limited orders": "한정 주문",
 "Weapon banner": "무기 배너",
 "Matrix banner": "칩셋 배너",
 "Base SSR rate": "기본 SSR 확률",
 "Base SR rate": "기본 SR 확률",
 "Hard SSR guarantee": "하드 SSR 보장",
 "Average rate with guarantee": "보장을 포함한 평균 확률",
 "pull in each cycle: #{{count}}": "각 주기의 뽑기: #{{count}}",
 "An SSR can drop early, but the fixed cycle still awards an SSR on pull 80.": "SSR은 조기에 나올 수 있지만, 고정 주기는 여전히 80번째 뽑기에서 SSR을 지급합니다.",
 "An SSR matrix can drop early, but the fixed cycle still awards an SSR on pull 40.": "SSR 칩셋은 조기에 나올 수 있지만, 고정 주기는 여전히 40번째 뽑기에서 SSR을 지급합니다.",
 "About the average rate:": "평균 확률 정보:",
 "2.00% for weapons and 4.20% for matrices are average SSR rates after accounting for the hard guarantee. They are not the chance on every individual pull.": "무기 2.00%와 칩셋 4.20%는 하드 보장을 반영한 평균 SSR 확률입니다. 개별 뽑기마다의 확률이 아닙니다.",
 "How pity works": "천장 작동 방식",
 "SSR and SR protection.": "SSR 및 SR 보호.",
 "An SSR is guaranteed on weapon pull 80 or matrix pull 40. Also, if no SR or SSR appears for {{srPity}} pulls, the next pull guarantees SR or higher.": "무기 뽑기 80번째 또는 칩셋 뽑기 40번째에 SSR이 보장됩니다. 또한 {{srPity}}번 뽑는 동안 SR 또는 SSR이 나오지 않으면 다음 뽑기에서 SR 이상이 보장됩니다.",
 "Pity carries over.": "천장은 이월됩니다.",
 "Limited weapon pity carries between weapon event banners; matrix pity carries between matrix event banners. The two tracks are independent.": "한정 무기 천장은 무기 이벤트 배너 사이에서, 칩셋 천장은 칩셋 이벤트 배너 사이에서 이월됩니다. 두 트랙은 서로 독립적입니다.",
 "Separate guarantees.": "별도의 보장.",
 "The rarity guarantee (SSR) and the featured-item result (50/50) are separate events. A win or loss does not change rarity pity.": "희귀도 보장(SSR)과 픽업 아이템 결과(50/50)는 별개의 이벤트입니다. 승리나 패배는 희귀도 천장을 바꾸지 않습니다.",
 "Early SSR.": "조기 SSR.",
 "An early drop does not reset the fixed guarantee cycle. For example, an SSR on pull 23 does not cancel the next guaranteed SSR on pull 80.": "조기 드롭은 고정 보장 주기를 초기화하지 않습니다. 예를 들어 23번째 뽑기의 SSR은 80번째 뽑기의 다음 보장 SSR을 취소하지 않습니다.",
 "Featured item: 50/50": "픽업 아이템: 50/50",
 "Standard SSR": "일반 SSR",
 "next SSR is standard": "다음 SSR은 일반입니다",
 "next SSR is featured": "다음 SSR은 픽업입니다",
 "standard 50/50 odds": "일반 50/50 확률",
 "Matrix slots": "칩셋 슬롯",
 "Currencies & shop": "재화 및 상점",
 "Weapons — Flame Gold.": "무기 — 플레임 골드.",
 "{{base}} per pull; a maxed SR duplicate grants +{{srBonus}}, and a maxed standard SSR duplicate grants +{{ssrBonus}} more.": "뽑기당 {{base}}; 최대 레벨 SR 중복은 +{{srBonus}}, 최대 레벨 일반 SSR 중복은 추가로 +{{ssrBonus}}을 지급합니다.",
 "Matrices — Overclocking Chips.": "칩셋 — 오버클러킹 칩.",
 "{{base}} chip per pull; matrix duplicates do not grant extra currency.": "뽑기당 칩 {{base}}개; 칩셋 중복은 추가 재화를 지급하지 않습니다.",
 "Shop exchange.": "상점 교환.",
