 "You can help update the site’s game data. It takes about 30 minutes and requires an installed PC copy of Tower of Fantasy.": "사이트의 게임 데이터 업데이트를 도울 수 있습니다. 약 30분이 걸리며, 설치된 PC 버전의 Tower of Fantasy가 필요합니다.",
