 "ToF resources": "ToF 자료",
 "ToF Hub Capture · Windows app": "ToF Hub Capture · Windows 앱",
 "Collect your build card and pull history": "빌드 카드와 뽑기 기록 수집",
 "The app uses WinDivert to read copies of the game’s TCP/UDP packets on your PC. It collects your build card and pull history from that data.": "이 앱은 WinDivert를 사용해 PC에서 게임의 TCP/UDP 패킷 사본을 읽습니다. 이 데이터에서 빌드 카드와 뽑기 기록을 수집합니다.",
 "Download for Windows": "Windows용 다운로드",
 "Download link coming soon": "다운로드 링크 준비 중",
 "Windows 10/11 · 64-bit · administrator rights for the network driver": "Windows 10/11 · 64비트 · 네트워크 드라이버를 위한 관리자 권한",
 "In short": "요약",
 "Get the app above and run it as administrator.": "위에서 앱을 받아 관리자 권한으로 실행하세요.",
 "Start before you log in": "로그인하기 전에 시작하세요",
 "Press Start, then log into your character in Hykros. If you are elsewhere, teleport to Hykros and log into your character again.": "시작을 누른 다음 Hykros에서 캐릭터에 로그인하세요. 다른 곳에 있다면 Hykros로 순간이동한 뒤 캐릭터에 다시 로그인하세요.",
 "Open two windows": "창 두 개 열기",
 "Upload the file": "파일 업로드",
 "Save .tofbuild and/or .tofwish and upload them here: Tools → Build, Tools → Wish.": ".tofbuild 및/또는 .tofwish를 저장한 뒤 여기에 업로드하세요: 도구 → 빌드, 도구 → 뽑기.",
 "Safe by design: it only watches, never touches": "설계상 안전: 감시만 하고 아무것도 건드리지 않습니다",
 "Read-only copy of traffic": "트래픽의 읽기 전용 사본",
 "No game memory access or file changes": "게임 메모리 접근이나 파일 변경 없음",
 "Sends nothing anywhere": "어디에도 아무것도 전송하지 않음",
 "How it works": "작동 방식",
 "Reads a copy of the traffic.": "트래픽 사본을 읽습니다.",
 "Only the game’s connections.": "게임의 연결만 읽습니다.",
 "Decoded on your PC.": "PC에서 디코딩됩니다.",
 "Sealed files.": "봉인된 파일.",
 "No network access of its own.": "자체 네트워크 접근 없음.",
 "The app makes no requests: no account, no telemetry, no auto-update. You decide which file to upload.": "앱은 요청을 보내지 않습니다: 계정, 원격 측정, 자동 업데이트 없음. 어떤 파일을 업로드할지는 사용자가 결정합니다.",
 "What the app never touches": "앱이 절대 건드리지 않는 것",
 "The game.": "게임.",
 "Nothing is injected into the game process, game files are not changed, no proxy, certificate or hook is installed.": "게임 프로세스에 아무것도 주입하지 않으며, 게임 파일을 변경하지 않고, 프록시, 인증서, 후킹을 설치하지 않습니다.",
 "Your accounts.": "사용자의 계정.",
 "Passwords and login tokens never reach the saved file, and the app removes all of its working files itself when it closes.": "비밀번호와 로그인 토큰은 저장 파일에 기록되지 않으며, 앱은 종료 시 작업 파일을 모두 스스로 삭제합니다.",
 "Your files.": "사용자의 파일.",
