 "Optional: PWG UID from the matching in-game top-up link in HottaBrowser.log; stored under the game UID after import": "선택 사항: HottaBrowser.log의 해당 게임 내 충전 링크에서 얻은 PWG UID; 가져온 뒤 게임 UID 아래 저장됨",
 "Combat stats, weapons, matrices, gear with pre-Titan values and Titan clicks, pet, relics, Supercomputing, Space Support": "전투 능력치, 무기, 칩셋, 타이탄 이전 값과 타이탄 클릭이 포함된 장비, 펫, 기어, 슈퍼컴퓨팅, 우주 지원",
