 "Average at 5 rolls = base + 5 × (min + max) / 2; maximum = base + 5 × max. The Gold rows are checked against the reference Stat ranges table on every run.": "5회 롤의 평균 = 기본 값 + 5 × (최소 + 최대) / 2; 최대치 = 기본 값 + 5 × 최대. 골드 행은 실행할 때마다 기준 능력치 범위 표와 대조됩니다.",
 "Chances by slot.": "슬롯별 확률.",
 "Each item names its pool (EquipmentDataTable → RandomModifyData). One draw uses positive weights; -1 marks a guaranteed stat.": "각 아이템은 풀을 지정합니다 (EquipmentDataTable → RandomModifyData). 한 번의 뽑기는 양수 가중치를 사용하며, -1은 보장된 능력치를 뜻합니다.",
 "Whole-item model.": "아이템 전체 모델.",
 "Rare properties.": "희귀 속성.",
 "EquipUncommonModifyData: each entry becomes available once the augmentation count reaches TupoCountLimited; chance = Weight / sum of available weights.": "EquipUncommonModifyData: 각 항목은 증폭 횟수가 TupoCountLimited에 도달하면 사용할 수 있게 됩니다. 확률 = 가중치 / 사용 가능한 가중치 합계.",
 "Roll chance.": "롤 확률.",
 "EquipUncommonRateData.UncommonRate per augmentation-count row; counts between rows are not confirmed.": "증폭 횟수별 행의 EquipUncommonRateData.UncommonRate; 행 사이의 횟수는 확인되지 않았습니다.",
 "Main-stat growth.": "주 능력치 성장.",
 "EquipRandomModifyData.TupoAddABSValueMap: five weighted bands per count; expected value assumes a uniform value inside a band.": "EquipRandomModifyData.TupoAddABSValueMap: 횟수별 가중 구간 다섯 개; 기대값은 구간 안에서 값이 균등하다고 가정합니다.",
 "Added stats.": "추가된 능력치.",
 "The ideal rule derived from captured items and used on the Tools pages (build-reference titanGrowth).": "캡처한 아이템에서 도출하고 도구 페이지에서 사용하는 이상적 규칙입니다(build-reference titanGrowth).",
 "Weights.": "가중치.",
 "AttributeStaticDataTable weight of every attribute, as used by the Build card CS rules.": "빌드 카드 전투력 규칙에서 사용하는 모든 속성의 AttributeStaticDataTable 가중치.",
 "Other systems.": "기타 시스템.",
 "Cost.": "비용.",
 "EquipStrengthenDataTable row N is the price of reaching +N (NeedItems, NeedGolds); a range is the sum of its rows.": "EquipStrengthenDataTable의 N번째 행은 +N에 도달하는 가격입니다(NeedItems, NeedGolds). 범위는 해당 행들의 합계입니다.",
 "Main stats.": "주 능력치.",
 "Base stats plus EquipStrengthenEffectPack growth and the stats unlocked every five levels, truncated like in the game.": "기본 능력치에 EquipStrengthenEffectPack 성장과 다섯 레벨마다 해금되는 능력치를 더하며, 게임과 같이 잘라냅니다.",
 "Success chance.": "성공 확률.",
 "Clicks.": "클릭.",
 "EquipSlotEvolution tables: experience per level, click outcomes with weights and eligible experience ranges; expected clicks assume excess experience is lost.": "EquipSlotEvolution 표: 레벨별 경험치, 가중치가 있는 클릭 결과와 대상 경험치 범위; 기대 클릭 수는 초과 경험치가 사라진다고 가정합니다.",
 "Versions.": "버전.",
 "MMO combat buffs.": "MMO 전투 버프.",
 "Node and skill data.": "노드 및 스킬 데이터.",
 "Graph.": "그래프.",
 "Display values.": "표시 값.",
 "Special effects.": "특수 효과.",
 "BuffObject and the localized descriptions are linked per level. Custom event behavior, stacking, and season gating are not computed from the buff assets.": "BuffObject와 현지화된 설명은 레벨별로 연결됩니다. 사용자 지정 이벤트 동작, 중첩, 시즌 게이팅은 버프 에셋에서 계산되지 않습니다.",
 "Costs.": "비용.",
 "System levels.": "시스템 레벨.",
 "Crit.": "치명타.",
 "CritFormula curves give the denominator D for each enemy level; chance = Crit / D.": "CritFormula 곡선은 각 적 레벨의 분모 D를 제공합니다. 확률 = 치명타 / D.",
 "Resistance.": "저항.",
 "DefenceFormula curves give K for each level; reduction = RES / (RES + K). Ignore and shred follow the documented community model.": "DefenceFormula 곡선은 각 레벨의 K를 제공합니다. 감소 = RES / (RES + K). 무시와 감소는 문서화된 커뮤니티 모델을 따릅니다.",
 "Servers.": "서버.",
 "The official server list the PC launcher downloads, plus China and Taiwan snapshots; the first digits of a UID are the server ID.": "PC 런처가 내려받는 공식 서버 목록과 중국 및 대만 스냅샷입니다. UID의 앞자리는 서버 ID입니다.",
