 "Permalink": "고정 링크",
 "A row is a triple: its module context (": "각 행은 세 가지 요소로 이루어진 삼중 항목입니다: 모듈 컨텍스트 (",
 "), its attribute / sub-table (e.g. ": "), 속성 / 하위 테이블 (예: ",
 "), and the source buff file. That raw triple is the ": "), 그리고 원본 버프 파일. 이 원시 삼중 항목이 ",
 " view.": " 보기입니다.",
 "Then, using the in-game console, each buff is pulled live and its real effect is verified, and a human-readable name is attached. That verified name is the ": "그다음 게임 내 콘솔을 사용해 각 버프를 실시간으로 가져와 실제 효과를 검증하고 사람이 읽을 수 있는 이름을 붙입니다. 이 검증된 이름이 ",
 "Combined": "통합",
 "Each table (module × attribute) is its own multiplier bucket. Values ": "각 테이블(모듈 × 속성)은 독립된 배율 묶음입니다. 한 테이블 ",
 " one table add together; ": " 안의 값은 함께 합산되며; 서로 다른 테이블은 ",
 "The critical point: two tables can show the ": "중요한 점: 두 테이블은 ",
 " display name (“Final Dmg”) and still be ": " 표시 이름(“Final Dmg”)을 가지고 있어도 ",
 " categories, because they live under different modules. In game they ": " 카테고리일 수 있습니다. 서로 다른 모듈 아래에 있기 때문입니다. 게임에서는 ",
 " even though the label looks identical. The same is true for the elemental tables (Ice / Fire / Volt / Phys attack).": " 라벨이 같아 보여도 그렇습니다. 속성 테이블(Ice / Fire / Volt / Phys 공격)도 마찬가지입니다.",
 "Multiplied": "곱해짐",
 "Almost everything you care about is Final Dmg plus the Elemental Dmg of your element. These split into a few ": "여러분이 신경 쓰는 거의 모든 것은 최종 DMG와 자신의 속성의 속성 DMG를 더한 값입니다. 이것들은 몇 가지 ",
 "main groups": "주요 그룹",
 " cross. To compare matrices you do ": " 으로 나뉩니다. 칩셋을 비교하려면 어떤 무기를 쓰는지도 ",
 " need to think about which weapons you run: matrices synergize among themselves by the simple Final Dmg + Elemental Dmg rule and never overlap with weapons. ": " 생각해야 합니다: 칩셋끼리는 단순한 최종 DMG + 속성 DMG 규칙으로 시너지를 내며, 무기와는 겹치지 않습니다. ",
 " and you will be exactly right.": " 이렇게 이해하면 정확합니다.",
 "If the buff is granted on a skill press / some action, it is ": "버프가 스킬 사용이나 어떤 동작으로 부여되면 ",
 "ACTIVE": "액티브",
 " (compare among actives).": " (액티브끼리 비교).",
 "If the buff is granted simply for the weapon existing in your build, it is ": "버프가 빌드에 있는 무기의 존재만으로 부여되면 ",
 "PASSIVE": "패시브",
 "Relics: Final and Elemental are counted separately, and relics do ": "기어: 최종과 속성은 따로 집계되며, 기어는 ",
 " combine with traits or matrices.": " 특성 또는 칩셋과 결합할 수 있습니다.",
 "Those specific relics are ": "그 특정 기어는 ",
 " bound by the group rules above. Relics appearing in ": " 위의 그룹 규칙에 따릅니다. 다음에 나타나는 기어는 ",
 "In the end, all resulting combat damage in your build scales as the product of two fundamental multiplier blocks: ": "결국 빌드의 모든 전투 피해는 두 개의 기본 배율 블록의 곱으로 조정됩니다: ",
 "Final Dmg × Elemental Dmg": "최종 DMG × 속성 DMG",
 "In turn, each of these two blocks is multiplied across its own independent categories: ": "차례로, 이 두 블록 각각은 자체적인 독립 카테고리에 걸쳐 곱해집니다: ",
 " from matrices multiplies by ": " 칩셋의 값에 곱하기 ",
 " from active weapon buffs, by ": " 액티브 무기 버프의 값에 곱하기 ",
 " from passive weapon buffs, traits, and relics. In the exact same way, ": " 패시브 무기 버프, 특성, 기어의 값. 정확히 같은 방식으로 ",
 " multiplies across matrices, weapon active, weapon passive, traits, and relics.": " 칩셋, 무기 액티브, 무기 패시브, 특성, 기어에 걸쳐 곱해집니다.",
 "Total Multiplier = Final Dmg × Elemental Dmg": "총 배율 = 최종 DMG × 속성 DMG",
 "• Final Dmg: Matrix × Weapon Active × Weapon Passive × Traits × Relics": "• 최종 DMG: 칩셋 × 무기 액티브 × 무기 패시브 × 특성 × 기어",
 "• Elemental Dmg: Matrix × Weapon Active × Weapon Passive × Traits × Relics": "• 속성 DMG: 칩셋 × 무기 액티브 × 무기 패시브 × 특성 × 기어",
 "Frost Dmg and Elemental Dmg are one and the same thing": "냉기 DMG와 속성 DMG는 같은 것입니다",
 "If one buff says ": "한 버프가 ",
 "\"Frost Dmg +X%\"": "\"냉기 DMG +X%\"",
 " and another says ": " 라고 하고 다른 버프가 ",
 "\"Elemental Dmg +Y%\"": "\"속성 DMG +Y%\"",
 "Drone": "드론",
 "Instead of placing Lan's simulacrum trait into character traits, the developers placed it directly into the Matrix module (": "개발자는 Lan의 레플리카 특성을 캐릭터 특성에 넣는 대신 칩셋 모듈에 직접 넣었습니다 (",
 ", there was already an established sub-table ": " 이미 정해진 하위 테이블 ",
 "ThunderAtkExtraUpMult": "ThunderAtkExtraUpMult",
 " (31 files). However, developers arbitrarily added a 'Be' prefix — ": " (파일 31개)이 있었습니다. 그런데 개발자는 임의로 'Be' 접두사를 붙이고 ― ",
 " (2 files) — and shoved new buffs there without any apparent logical rationale, creating an unintentional separate multiplier:": " (파일 2개) ― 논리적인 근거 없이 새 버프를 그곳에 밀어 넣어, 의도치 않은 별도의 배율을 만들었습니다:",
