 "Add image": "이미지 추가",
 "Filter by player type": "플레이어 유형별 필터",
 "WISH TRACKER / IMPORT": "뽑기 추적기 / 가져오기",
 "Bring in your order history": "주문 기록 가져오기",
 "Capture your game history, then upload its file here. We validate the format and show the processing status before saving.": "게임 기록을 캡처한 뒤 파일을 여기에 업로드하세요. 저장하기 전에 형식을 검증하고 처리 상태를 보여 줍니다.",
 "Start the app": "앱 실행",
 "Download ToF Hub Capture, run it and press Start before you enter the game.": "ToF Hub Capture를 내려받아 실행하고, 게임에 들어가기 전에 시작을 누르세요.",
 "Open the history": "기록 열기",
 "Press Save pull history and upload the .tofwish here. Importing again never duplicates pulls.": "뽑기 기록 저장을 누르고 .tofwish를 여기에 업로드하세요. 다시 가져와도 뽑기가 중복되지 않습니다.",
 "What the app does": "앱이 하는 일",
 "Download and safety details": "다운로드 및 안전 정보",
