 "without an exact banner": "정확한 배너 없음",
 "Open profile history": "프로필 기록 열기",
 "Could not import this file.": "이 파일을 가져오지 못했습니다.",
 "Choose a .tofwish file no larger than 4 MiB.": "4 MiB 이하의 .tofwish 파일을 선택하세요.",
 "Import is not configured on the server yet. No file was sent.": "서버에 가져오기가 아직 설정되지 않았습니다. 파일은 전송되지 않았습니다.",
 "The file contains your game UID and order history. Upload only a file from your own account.": "이 파일에는 게임 UID와 주문 기록이 들어 있습니다. 본인 계정의 파일만 업로드하세요.",
 "Do I need to install anything else?": "다른 것을 설치해야 하나요?",
 "Only the app. The WinDivert driver ships inside it; Windows asks for administrator rights to read packets.": "앱만 있으면 됩니다. WinDivert 드라이버가 앱에 포함되어 있으며, 패킷을 읽으려면 Windows가 관리자 권한을 요청합니다.",
 "Why open the history in game?": "기록은 왜 게임에서 열어야 하나요?",
 "The game sends history page by page only when you open it. Page back to your very first pull.": "게임은 열 때만 기록을 페이지 단위로 보냅니다. 첫 뽑기까지 뒤로 넘겨 주세요.",
 "What happens when I import twice?": "두 번 가져오면 어떻게 되나요?",
 "Matching records are identified by UID, original banner code, group time and position in the ten-pull batch. They are not added twice.": "일치하는 기록은 UID, 원본 배너 코드, 그룹 시간, 10회 뽑기 묶음 안의 위치로 식별됩니다. 두 번 추가되지 않습니다.",
