 "Messages": "메시지",
 "Each page message is a separate feedback item. Scores belong to the review as a whole.": "페이지 메시지는 각각 별도의 피드백 항목입니다. 점수는 리뷰 전체에 속합니다.",
 "How is ToF Hub working for you?": "ToF Hub는 사용해 보니 어떠신가요?",
 "Rate the work behind the site, or tell us what would make it more useful. Answer only the questions you have an opinion on.": "사이트의 작업 결과를 평가하거나, 더 유용해지려면 무엇이 필요한지 알려 주세요. 의견이 있는 질문에만 답해 주셔도 됩니다.",
 "Your experience": "사용 경험",
