 "Not at all": "전혀",
 "Completely happy": "아주 만족",
 "Trust in the data": "데이터 신뢰도",
 "How well does the information match your experience and checks in the game?": "정보가 게임에서 직접 경험하고 확인한 내용과 얼마나 일치하나요?",
 "Frequent mismatches": "불일치가 잦음",
