 "How noticeable are the traces of AI in the site?": "사이트에서 AI의 흔적이 얼마나 눈에 띄나요?",
 "Not noticeable": "눈에 띄지 않음",
 "Very noticeable": "매우 눈에 띔",
 "AI was used to speed up development, refine the visuals and assist with other tasks. Here, “AI slop” means generic, misplaced or insufficiently polished AI output in the design, text or interface.": "AI는 개발 속도를 높이고, 시각 요소를 다듬고, 기타 작업을 돕는 데 사용되었습니다. 여기서 “AI 슬롭”은 디자인, 글 또는 인터페이스에서 일반적이거나 어울리지 않거나 충분히 다듬어지지 않은 AI 결과물을 뜻합니다.",
 "Where is it especially noticeable? (optional)": "특히 어디에서 눈에 띄나요? (선택)",
 "A higher AI visibility score means more noticeable traces of AI. It is kept separate from quality ratings.": "AI 흔적 점수가 높을수록 AI의 흔적이 더 눈에 띈다는 뜻입니다. 품질 평가와는 별도로 집계됩니다.",
 "Suggestions & page feedback": "제안 및 페이지 피드백",
 "Each message is saved separately with its page and category. You can return at any time and send another one.": "각 메시지는 페이지와 분류와 함께 따로 저장됩니다. 언제든 다시 와서 다른 메시지를 보낼 수 있습니다.",
