 "Choose a page and write a message in each added entry, or remove the empty entry.": "추가한 항목마다 페이지를 선택하고 메시지를 작성하거나, 빈 항목을 제거해 주세요.",
 "The combined comments must be no longer than 12,000 characters.": "전체 의견은 12,000자를 넘을 수 없습니다.",
 "Feedback could not be saved. Your answers are still here; please try again.": "피드백을 저장하지 못했습니다. 작성한 답변은 그대로 있으니 다시 시도해 주세요.",
 "The feedback limit has been reached. Your answers are still here; please try again later.": "피드백 제출 한도에 도달했습니다. 작성한 답변은 그대로 있으니 나중에 다시 시도해 주세요.",
 "Thank you. Your feedback has been saved.": "감사합니다. 피드백이 저장되었습니다.",
 "Your page messages were saved as separate feedback items. You can return through the footer whenever you have something to add.": "페이지 메시지는 각각 별도의 피드백 항목으로 저장되었습니다. 더 하고 싶은 말이 있으면 언제든 푸터를 통해 다시 찾아 주세요.",
