 "Debuff table placement: Despite being a relic, its damage taken modifier is classified under the enemy debuff table.": "디버프 표 배치: 기어이지만, 받는 피해 수정자는 적 디버프 표로 분류됩니다.",
 "Dual-table multiplier: The same buff file exists in two distinct tables simultaneously, multiplying together: (1 + 0.10) × (1 + 0.10) = 1.21×.": "이중 표 배율: 같은 버프 파일이 두 개의 서로 다른 표에 동시에 있어 함께 곱해집니다: (1 + 0.10) × (1 + 0.10) = 1.21배.",
 "Target vulnerability debuff: Relic field applies damage vulnerability directly to targets inside the rift.": "대상 취약 디버프: 기어 필드가 균열 안의 대상에게 피해 취약을 직접 적용합니다.",
