 "Disclaimer: Game Truth vs. Developer Inconsistencies": "면책 조항: 게임의 실제와 개발자의 불일치",
 "The Multype tables 100% accurately reflect the real running game engine and active memory structures. However, in-game skill descriptions and translations do not always reflect the truth. Game developers occasionally introduce human errors, typos, or odd architectural quirks, causing an intuitively assumed category to land in a completely unexpected bucket under the hood.": "Multype 표는 실제로 실행 중인 게임 엔진과 활성 메모리 구조를 100% 정확하게 반영합니다. 하지만 게임 내 스킬 설명과 번역은 항상 진실을 반영하지는 않습니다. 게임 개발자는 가끔 사람의 실수, 오타, 이상한 구조적 특이점을 도입하므로, 직관적으로 예상한 카테고리가 내부적으로 전혀 예상치 못한 묶음에 들어가기도 합니다.",
 "Example 1: Lan Trait placed inside the Matrix category": "예시 1: 칩셋 카테고리 안에 있는 Lan 특성",
 "8 SUB COLUMNS": "하위 열 8개",
 "8 FILES": "파일 8개",
 "Example 2: Arbitrary 'Be' prefix in WeaponPassive (ThunderAtkBeExtraUpMult)": "예시 2: WeaponPassive의 임의 'Be' 접두사 (ThunderAtkBeExtraUpMult)",
 "2 FILES": "파일 2개",
 "31 FILES": "파일 31개",
 "These are merely the most striking examples of game descriptions diverging from actual engine code. Multype reveals the raw reality of the engine — letting you build around how buffs genuinely calculate in combat rather than how tooltips describe them.": "이는 게임 설명이 실제 엔진 코드와 다른 가장 눈에 띄는 예시일 뿐입니다. Multype은 엔진의 원시 실체를 보여 주며, 툴팁이 설명하는 방식이 아니라 전투에서 버프가 실제로 계산되는 방식을 기준으로 빌드할 수 있게 해 줍니다.",
